// Downloads the sample report as a real PDF generated by the LandVerify server.
// Throws a readable error if the server cannot produce it, so no button ever claims a download that did not happen.
export async function downloadSamplePdf() {
  let res;
  try { res = await fetch('/api/public/sample-report.pdf'); }
  catch { throw new Error('Cannot reach the LandVerify server. Use Print to save the report as a PDF from your browser instead.'); }
  const type = res.headers.get('content-type') || '';
  if (!res.ok || !type.includes('pdf')) throw new Error('The PDF is not available from this server. Use Print to save the report as a PDF from your browser instead.');
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'LandVerify-sample-report-LV-SAMPLE-0142.pdf';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}
